import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.regex.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    // Custom filter: strip obvious attack patterns but allow legitimate queries
    private String sanitizeInput(String input) {
        if (input == null) return null;
        // Remove comment sequences
        input = input.replaceAll("/\\*.*?\\*/", "");
        // Remove double-dash comments
        input = input.replaceAll("--", "");
        // Collapse multiple spaces
        input = input.replaceAll("\\s+", " ");
        return input.trim();
    }

    private boolean isValidDateRange(String start, String end) {
        // Loose validation - accepts YYYY-MM-DD but doesn't enforce strictly
        Pattern p = Pattern.compile(".*\\d{4}.*");
        return (start != null && p.matcher(start).matches() && 
                end != null && p.matcher(end).matches());
    }

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) 
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String startDate = sanitizeInput(req.getParameter("start"));
        String endDate = sanitizeInput(req.getParameter("end"));
        String department = sanitizeInput(req.getParameter("dept"));
        String sortCol = sanitizeInput(req.getParameter("sort"));

        if (!isValidDateRange(startDate, endDate)) {
            resp.sendError(400, "Invalid date range");
            return;
        }

        // Whitelist report types
        if (!"sales".equals(reportType) && !"inventory".equals(reportType) 
            && !"hr".equals(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        String table = reportType + "_reports";

        // Build query - sort column is validated against known columns
        String[] allowedSorts = {"date", "amount", "name", "id", "department"};
        boolean sortValid = false;
        if (sortCol != null) {
            for (String s : allowedSorts) {
                if (s.equalsIgnoreCase(sortCol)) { sortValid = true; break; }
            }
        }

        String query;
        if (department != null && !department.isEmpty()) {
            // Vulnerable: department is concatenated despite sanitizeInput
            query = "SELECT id, date, amount, name, department FROM " + table +
                    " WHERE date BETWEEN '" + startDate + "' AND '" + endDate + "'" +
                    " AND department = '" + department + "'";
        } else {
            query = "SELECT id, date, amount, name, department FROM " + table +
                    " WHERE date BETWEEN '" + startDate + "' AND '" + endDate + "'";
        }

        if (sortValid) {
            query += " ORDER BY " + sortCol;
        }

        resp.setContentType("application/json");
        PrintWriter out = resp.getWriter();

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            out.print("[\n");
            boolean first = true;
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.print("  {");
                for (int i = 1; i <= cols; i++) {
                    if (i > 1) out.print(", ");
                    out.print("\"" + meta.getColumnName(i) + "\": ");
                    out.print("\"" + rs.getString(i) + "\"");
                }
                out.print("}");
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            resp.sendError(500, "Query failed");
        }
    }
}
